                            <button onClick={() => updateQuantity(index, 1)} className="text-stone-400 hover:text-white">
                              <Plus className="w-3 h-3" />
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {cart.length > 0 && (
