                >
                  {checkoutSuccess ? (
                    <>
                      <Check className="w-4 h-4 text-white" />
                      <span>Order Placed! Roasting Soon...</span>
                    </>
                  ) : (
                    <>
                      <ShoppingBag className="w-4 h-4" />
                      <span>Proceed to Checkout</span>
                    </>
                  )}
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

