    setCart(prevCart => {
      const existingIndex = prevCart.findIndex(item => item.coffee.id === coffee.id && item.grind === grind);
      if (existingIndex > -1) {
        const newCart = [...prevCart];
        newCart[existingIndex].quantity += 1;
        return newCart;
      }
      return [...prevCart, { coffee, quantity: 1, grind }];
    });
