                    className={`w-full py-2.5 rounded-md font-bold text-xs transition-all ${selectedPlan === plan.id ? 'bg-[#e50914] hover:bg-[#b80710] text-white shadow-lg shadow-[#e50914]/30' : 'bg-zinc-800 hover:bg-zinc-700 text-zinc-200'}`}
                  >
                    {selectedPlan === plan.id ? 'Current Plan' : `Switch to ${plan.name}`}
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
