import React, { useState } from 'react';
import { 
  Sparkles, 
  Plus, 
  Trash2, 
  CheckCircle2, 
  Circle, 
  ListTodo, 
  Flame, 
  Clock, 
  Search, 
  Filter, 
  BarChart3, 
  RotateCcw, 
  Minus, 
  ArrowRight,
  CheckSquare,
  Calendar,
  Tag
} from 'lucide-react';

interface Todo {
  id: string;
  text: string;
  completed: boolean;
  priority: 'low' | 'medium' | 'high';
  category: 'Work' | 'Personal' | 'Code' | 'Design';
  dueDate: string;
}

export default function App() {
  // Navigation & View State
  const [activeTab, setActiveTab] = useState<'tasks' | 'counter' | 'dashboard'>('tasks');

  // Counter State
  const [count, setCount] = useState<number>(5);
  const [step, setStep] = useState<number>(1);
  const [targetGoal, setTargetGoal] = useState<number>(10);

  // Todo State
  const [todos, setTodos] = useState<Todo[]>([
    { id: '1', text: 'Refactor React 19 component architecture', completed: true, priority: 'high', category: 'Code', dueDate: 'Today' },
    { id: '2', text: 'Design glassmorphic dark mode dashboard layout', completed: false, priority: 'high', category: 'Design', dueDate: 'Tomorrow' },
    { id: '3', text: 'Write TypeScript definitions for API payloads', completed: false, priority: 'medium', category: 'Code', dueDate: 'Oct 24' },
    { id: '4', text: 'Review pull requests for NovaForge design system', completed: false, priority: 'low', category: 'Work', dueDate: 'Oct 26' },
  ]);
  const [newTodoText, setNewTodoText] = useState('');
  const [newPriority, setNewPriority] = useState<'low' | 'medium' | 'high'>('medium');
  const [newCategory, setNewCategory] = useState<'Work' | 'Personal' | 'Code' | 'Design'>('Code');
  const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  // Todo Handlers
  const handleAddTodo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTodoText.trim()) return;

    const newTodo: Todo = {
      id: Date.now().toString(),
      text: newTodoText.trim(),
      completed: false,
      priority: newPriority,
      category: newCategory,
      dueDate: 'Today'
    };

    setTodos([newTodo, ...todos]);
    setNewTodoText('');
  };

  const toggleTodo = (id: string) => {
    setTodos(todos.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const deleteTodo = (id: string) => {
    setTodos(todos.filter(t => t.id !== id));
  };

  // Filtered Todos
  const filteredTodos = todos.filter(t => {
    const matchesSearch = t.text.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesFilter = filter === 'all' ? true : filter === 'active' ? !t.completed : t.completed;
    const matchesCategory = selectedCategory === 'All' || t.category === selectedCategory;
    return matchesSearch && matchesFilter && matchesCategory;
  });

  const completedCount = todos.filter(t => t.completed).length;
  const progressPercent = todos.length > 0 ? Math.round((completedCount / todos.length) * 100) : 0;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans selection:bg-indigo-500 selection:text-white">
      {/* Top Header */}
      <header className="border-b border-slate-800 bg-slate-900/60 backdrop-blur-xl sticky top-0 z-50 px-6 py-4">
        <div className="max-w-6xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-500 flex items-center justify-center shadow-lg shadow-indigo-500/30">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight bg-gradient-to-r from-white via-slate-200 to-slate-400 bg-clip-text text-transparent">
                ACCEPTANCE TEST HEADING V2
              </h1>
              <p className="text-xs text-slate-400">Next-gen productivity & state management suite</p>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex items-center bg-slate-950/80 p-1.5 rounded-xl border border-slate-800/80 shadow-inner">
            <button
              onClick={() => setActiveTab('tasks')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-medium transition-all ${
                activeTab === 'tasks' 
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-500/25' 
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-900'
              }`}
            >
              <CheckSquare className="w-4 h-4" />
              <span>Task Master ({todos.length})</span>
            </button>
            <button
              onClick={() => setActiveTab('counter')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-medium transition-all ${
                activeTab === 'counter' 
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-500/25' 
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-900'
              }`}
            >
              <Flame className="w-4 h-4" />
              <span>Counter Hub</span>
            </button>
            <button
              onClick={() => setActiveTab('dashboard')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-medium transition-all ${
                activeTab === 'dashboard' 
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-500/25' 
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-900'
              }`}
            >
              <BarChart3 className="w-4 h-4" />
              <span>Overview</span>
            </button>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 max-w-6xl w-full mx-auto p-6 md:p-8">

        {/* --- VIEW 1: TASK MASTER (TODOS) --- */}
        {activeTab === 'tasks' && (
          <div className="space-y-6 animate-fadeIn">
            {/* Quick Stats banner */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-5 flex items-center justify-between shadow-lg">
                <div>
                  <p className="text-xs font-medium text-slate-400 uppercase tracking-wider">Total Tasks</p>
                  <p className="text-2xl font-bold mt-1 text-slate-100">{todos.length}</p>
                </div>
                <div className="w-12 h-12 rounded-xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-400">
                  <ListTodo className="w-6 h-6" />
                </div>
              </div>

              <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-5 flex items-center justify-between shadow-lg">
                <div>
                  <p className="text-xs font-medium text-slate-400 uppercase tracking-wider">Completed</p>
                  <p className="text-2xl font-bold mt-1 text-emerald-400">{completedCount}</p>
                </div>
                <div className="w-12 h-12 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
                  <CheckCircle2 className="w-6 h-6" />
                </div>
              </div>

              <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-5 flex items-center justify-between shadow-lg">
                <div>
                  <p className="text-xs font-medium text-slate-400 uppercase tracking-wider">Completion Rate</p>
                  <p className="text-2xl font-bold mt-1 text-violet-400">{progressPercent}%</p>
                </div>
                <div className="w-12 h-12 rounded-xl bg-violet-500/10 border border-violet-500/20 flex items-center justify-center text-violet-400">
                  <BarChart3 className="w-6 h-6" />
                </div>
              </div>
            </div>

            {/* Add Todo Form */}
            <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl">
              <h2 className="text-sm font-semibold text-slate-300 mb-4 flex items-center gap-2">
                <Plus className="w-4 h-4 text-indigo-400" />
                Create New Task
              </h2>
              <form onSubmit={handleAddTodo} className="space-y-4">
                <div className="flex flex-col md:flex-row gap-3">
                  <div className="relative flex-1">
                    <Search className="absolute left-3.5 top-3.5 w-4 h-4 text-slate-500" />
                    <input
                      type="text"
                      value={newTodoText}
                      onChange={(e) => setNewTodoText(e.target.value)}
                      placeholder="What needs to be accomplished today?"
                      className="w-full bg-slate-950 border border-slate-800 rounded-xl pl-10 pr-4 py-3 text-sm text-slate-200 placeholder-slate-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all"
                    />
                  </div>

                  <select
                    value={newPriority}
                    onChange={(e: any) => setNewPriority(e.target.value)}
                    className="bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-slate-300 focus:outline-none focus:border-indigo-500"
                  >
                    <option value="low">Low Priority</option>
                    <option value="medium">Medium Priority</option>
                    <option value="high">High Priority</option>
                  </select>

                  <select
                    value={newCategory}
                    onChange={(e: any) => setNewCategory(e.target.value)}
                    className="bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-slate-300 focus:outline-none focus:border-indigo-500"
                  >
                    <option value="Code">Code</option>
                    <option value="Design">Design</option>
                    <option value="Work">Work</option>
                    <option value="Personal">Personal</option>
                  </select>

                  <button
                    type="submit"
                    className="inline-flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 active:scale-95 transition-all text-white font-medium text-sm rounded-xl shadow-lg shadow-indigo-500/25"
                  >
                    <Plus className="w-4 h-4" />
                    <span>Add Task</span>
                  </button>
                </div>
              </form>
            </div>

            {/* Todo Controls & Filters */}
            <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-slate-900/60 border border-slate-800/80 p-4 rounded-2xl">
              {/* Status Filters */}
              <div className="flex items-center gap-1 bg-slate-950 p-1 rounded-xl border border-slate-800 w-full md:w-auto">
                <button
                  onClick={() => setFilter('all')}
                  className={`flex-1 md:flex-initial px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${
                    filter === 'all' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-slate-200'
                  }`}
                >
                  All ({todos.length})
                </button>
                <button
                  onClick={() => setFilter('active')}
                  className={`flex-1 md:flex-initial px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${
                    filter === 'active' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-slate-200'
                  }`}
                >
                  Active ({todos.filter(t => !t.completed).length})
                </button>
                <button
                  onClick={() => setFilter('completed')}
                  className={`flex-1 md:flex-initial px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${
                    filter === 'completed' ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-slate-200'
                  }`}
                >
                  Completed ({completedCount})
                </button>
              </div>

              {/* Category Filter */}
              <div className="flex items-center gap-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
                <span className="text-xs text-slate-400 flex items-center gap-1">
                  <Tag className="w-3.5 h-3.5" /> Tag:
                </span>
                {['All', 'Code', 'Design', 'Work', 'Personal'].map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`px-3 py-1 rounded-lg text-xs font-medium border transition-all ${
                      selectedCategory === cat 
                        ? 'bg-indigo-500/10 border-indigo-500/40 text-indigo-300' 
                        : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-slate-700'
                    }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>

            {/* Todo Items List */}
            <div className="space-y-3">
              {filteredTodos.length === 0 ? (
                <div className="bg-slate-900/40 border border-slate-800/80 rounded-2xl p-12 text-center">
                  <div className="w-12 h-12 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-3 text-slate-500">
                    <CheckSquare className="w-6 h-6" />
                  </div>
                  <h3 className="text-base font-medium text-slate-300">No tasks found</h3>
                  <p className="text-xs text-slate-500 mt-1">Try creating a new task or changing your filters.</p>
                </div>
              ) : (
                filteredTodos.map((todo) => (
                  <div
                    key={todo.id}
                    className={`group bg-slate-900/80 border rounded-2xl p-4 flex items-center justify-between gap-4 transition-all duration-200 hover:border-slate-700 hover:shadow-lg ${
                      todo.completed ? 'border-emerald-900/30 bg-slate-900/40 opacity-75' : 'border-slate-800/80'
                    }`}
                  >
                    <div className="flex items-center gap-3.5 min-w-0">
                      <button
                        onClick={() => toggleTodo(todo.id)}
                        className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${
                          todo.completed 
                            ? 'bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/20' 
                            : 'border border-slate-700 hover:border-indigo-500 bg-slate-950'
                        }`}
                      >
                        {todo.completed ? <CheckCircle2 className="w-4 h-4" /> : <Circle className="w-4 h-4 text-transparent" />}
                      </button>
                      <div className="min-w-0">
                        <p className={`text-sm font-medium truncate transition-all ${
                          todo.completed ? 'line-through text-slate-500' : 'text-slate-200'
                        }`}>
                          {todo.text}
                        </p>
                        <div className="flex items-center gap-2 mt-1">
                          <span className={`text-[10px] px-2 py-0.5 rounded-md font-medium uppercase tracking-wider ${
                            todo.priority === 'high' ? 'bg-rose-500/10 text-rose-400 border border-rose-500/20' :
                            todo.priority === 'medium' ? 'bg-amber-500/10 text-amber-400 border border-amber-500/20' :
                            'bg-blue-500/10 text-blue-400 border border-blue-500/20'
                          }`}>
                            {todo.priority}
                          </span>
                          <span className="text-[10px] px-2 py-0.5 rounded-md font-medium bg-slate-800 text-slate-300">
                            {todo.category}
                          </span>
                          <span className="text-[10px] text-slate-500 flex items-center gap-1">
                            <Calendar className="w-3 h-3" /> {todo.dueDate}
                          </span>
                        </div>
                      </div>
                    </div>

                    <button
                      onClick={() => deleteTodo(todo.id)}
                      className="opacity-0 group-hover:opacity-100 p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-500/10 rounded-xl transition-all"
                      title="Delete Task"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* --- VIEW 2: COUNTER HUB --- */}
        {activeTab === 'counter' && (
          <div className="max-w-2xl mx-auto space-y-6 animate-fadeIn">
            <div className="bg-slate-900/90 border border-slate-800 rounded-3xl p-8 shadow-2xl text-center relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-600/10 rounded-full blur-3xl pointer-events-none" />

              <div className="w-16 h-16 bg-gradient-to-tr from-indigo-600 to-violet-500 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-indigo-500/30 text-white">
                <Flame className="w-8 h-8 animate-pulse" />
              </div>

              <h2 className="text-xl font-bold tracking-tight mb-1 text-slate-100">Interactive Counter Hub</h2>
              <p className="text-slate-400 text-sm mb-8">
                Test state updates, increments, step multipliers, and target goals.
              </p>

              {/* Main Counter Display */}
              <div className="my-8">
                <div className="text-7xl md:text-8xl font-extrabold tracking-tight bg-gradient-to-r from-white via-indigo-200 to-indigo-400 bg-clip-text text-transparent mb-2">
                  {count}
                </div>
                <p className="text-xs text-slate-500 uppercase tracking-widest font-semibold">Current Value</p>
              </div>

              {/* Progress bar towards goal */}
              <div className="max-w-md mx-auto mb-8 bg-slate-950 p-4 rounded-2xl border border-slate-800">
                <div className="flex justify-between text-xs text-slate-400 mb-2">
                  <span>Target Goal: {targetGoal}</span>
                  <span>{Math.min(100, Math.round((count / targetGoal) * 100))}%</span>
                </div>
                <div className="w-full bg-slate-900 h-2 rounded-full overflow-hidden">
                  <div 
                    className="bg-gradient-to-r from-indigo-500 to-violet-500 h-full transition-all duration-300"
                    style={{ width: `${Math.min(100, (count / targetGoal) * 100)}%` }}
                  />
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex flex-wrap items-center justify-center gap-3 mb-8">
                <button
                  onClick={() => setCount(c => c - step)}
                  className="inline-flex items-center gap-2 px-6 py-3 bg-slate-800 hover:bg-slate-700 active:scale-95 transition-all text-white font-medium text-sm rounded-xl border border-slate-700 shadow-lg"
                >
                  <Minus className="w-4 h-4" />
                  <span>Decrease (-{step})</span>
                </button>

                <button
                  onClick={() => setCount(c => c + step)}
                  className="inline-flex items-center gap-2 px-8 py-3 bg-indigo-600 hover:bg-indigo-500 active:scale-95 transition-all text-white font-semibold text-sm rounded-xl shadow-xl shadow-indigo-500/30"
                >
                  <Plus className="w-4 h-4" />
                  <span>Increase (+{step})</span>
                </button>

                <button
                  onClick={() => setCount(0)}
                  className="inline-flex items-center gap-2 px-5 py-3 bg-slate-800 hover:bg-rose-500/20 hover:text-rose-400 hover:border-rose-500/40 active:scale-95 transition-all text-slate-300 font-medium text-sm rounded-xl border border-slate-700"
                >
                  <RotateCcw className="w-4 h-4" />
                  <span>Reset</span>
                </button>
              </div>

              {/* Configurations */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-md mx-auto pt-6 border-t border-slate-800">
                <div className="text-left">
                  <label className="block text-xs font-medium text-slate-400 mb-2">Step Increment</label>
                  <div className="flex gap-2">
                    {[1, 5, 10].map((s) => (
                      <button
                        key={s}
                        onClick={() => setStep(s)}
                        className={`flex-1 py-2 text-xs font-semibold rounded-lg border transition-all ${
                          step === s 
                            ? 'bg-indigo-600 border-indigo-500 text-white shadow-md shadow-indigo-500/20' 
                            : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-slate-700'
