                  >
                    <option value={10}>10 Points</option>
                    <option value={25}>25 Points</option>
                    <option value={50}>50 Points</option>
                    <option value={100}>100 Points</option>
                  </select>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* --- VIEW 3: OVERVIEW & SYSTEM STATUS --- */}
        {activeTab === 'dashboard' && (
          <div className="space-y-6 animate-fadeIn">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl">
                <h3 className="text-base font-bold text-slate-200 mb-4 flex items-center gap-2">
                  <Sparkles className="w-5 h-5 text-indigo-400" />
                  System Architecture
                </h3>
                <p className="text-sm text-slate-400 leading-relaxed mb-4">
                  NovaForge Task Master is engineered with React 19, TypeScript, and modern Tailwind CSS. It features reactive component state, robust filtering algorithms, and a sleek dark glassmorphic UI.
                </p>
                <div className="space-y-2">
                  <div className="flex justify-between text-xs py-2 border-b border-slate-800 text-slate-400">
                    <span>Framework</span>
                    <span className="font-semibold text-slate-200">React 19 + Vite</span>
                  </div>
                  <div className="flex justify-between text-xs py-2 border-b border-slate-800 text-slate-400">
                    <span>Styling System</span>
                    <span className="font-semibold text-slate-200">Tailwind CSS v3</span>
                  </div>
                  <div className="flex justify-between text-xs py-2 text-slate-400">
                    <span>Iconography</span>
                    <span className="font-semibold text-slate-200">Lucide React</span>
                  </div>
                </div>
              </div>

              <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl flex flex-col justify-between">
                <div>
                  <h3 className="text-base font-bold text-slate-200 mb-4 flex items-center gap-2">
                    <Clock className="w-5 h-5 text-emerald-400" />
                    Productivity Status
                  </h3>
                  <div className="space-y-4">
                    <div>
                      <div className="flex justify-between text-xs text-slate-400 mb-1">
                        <span>Tasks Completed</span>
                        <span>{completedCount} / {todos.length}</span>
                      </div>
                      <div className="w-full bg-slate-950 h-2 rounded-full overflow-hidden border border-slate-800">
