                          className="bg-emerald-500 h-full transition-all duration-300"
                          style={{ width: `${progressPercent}%` }}
                        />
                      </div>
                    </div>
                    <div className="p-4 rounded-xl bg-slate-950 border border-slate-800">
                      <p className="text-xs text-slate-300 font-medium">✨ Pro Tip:</p>
                      <p className="text-xs text-slate-400 mt-1">
                        Switch to the Counter Hub to test incremental states, or use the Task Master tab to organize your daily sprints.
                      </p>
                    </div>
                  </div>
                </div>

                <button
                  onClick={() => setActiveTab('tasks')}
                  className="mt-6 w-full inline-flex items-center justify-center gap-2 py-2.5 bg-slate-800 hover:bg-slate-700 text-white font-medium text-xs rounded-xl transition-all"
                >
                  <span>Go to Task Master</span>
                  <ArrowRight className="w-4 h-4" />
