            </div>
          </div>
        )}

      </main>

      {/* Footer */}
      <footer className="border-t border-slate-800/80 bg-slate-900/40 py-6 px-6 mt-auto text-center text-xs text-slate-500">
        <p>NovaForge Task Master &copy; {new Date().getFullYear()} — Built with React 19 & Tailwind CSS.</p>
      </footer>
