                </button>
              </div>

              <div className="flex flex-wrap items-center justify-between gap-3 pt-1">
                <div className="flex flex-wrap items-center gap-3">
                  {/* Priority Selector */}
                  <div className="flex items-center gap-1.5 bg-slate-950/60 border border-slate-800 rounded-lg p-1">
                    <span className="text-[11px] text-slate-400 px-2 font-medium">Priority:</span>
                    {(['low', 'medium', 'high'] as const).map(p => (
                      <button
                        key={p}
                        type="button"
                        onClick={() => setNewPriority(p)}
                        className={`text-xs px-2.5 py-1 rounded-md capitalize font-medium transition-all ${
                          newPriority === p
                            ? p === 'high' ? 'bg-rose-500/20 text-rose-300 border border-rose-500/30'
                              : p === 'medium' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30'
                              : 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30'
                            : 'text-slate-400 hover:text-slate-200'
                        }`}
                      >
                        {p}
                      </button>
                    ))}
                  </div>

                  {/* Category Selector */}
                  <div className="flex items-center gap-1.5 bg-slate-950/60 border border-slate-800 rounded-lg p-1">
                    <span className="text-[11px] text-slate-400 px-2 font-medium">Category:</span>
                    {(['Work', 'Personal', 'Dev'] as const).map(c => (
                      <button
                        key={c}
                        type="button"
                        onClick={() => setNewCategory(c)}
                        className={`text-xs px-2.5 py-1 rounded-md font-medium transition-all ${
                          newCategory === c
                            ? 'bg-indigo-500/20 text-indigo-300 border border-indigo-500/30'
                            : 'text-slate-400 hover:text-slate-200'
                        }`}
                      >
                        {c}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </form>
          </div>

          {/* Task Management & Filters */}
          <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-6 shadow-xl backdrop-blur-md flex flex-col gap-5">

            {/* Search & Tabs Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              {/* Filter Tabs */}
              <div className="flex items-center gap-1 bg-slate-950 p-1 rounded-xl border border-slate-800">
                {(['all', 'active', 'completed'] as const).map((tab) => (
                  <button
                    key={tab}
                    onClick={() => setFilter(tab)}
                    className={`px-4 py-1.5 rounded-lg text-xs font-semibold capitalize transition-all ${
                      filter === tab
                        ? 'bg-indigo-600 text-white shadow-md shadow-indigo-600/30'
                        : 'text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    {tab}
                  </button>
                ))}
              </div>

              {/* Search input */}
              <div className="relative min-w-[220px]">
                <Search className="w-4 h-4 text-slate-500 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search tasks..."
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl pl-9 pr-3 py-1.5 text-xs text-slate-100 placeholder-slate-500 focus:outline-none focus:border-indigo-500 transition-all"
                />
              </div>
            </div>

            {/* Category Sub-filter pills */}
            <div className="flex items-center gap-2 overflow-x-auto pb-1">
              <span className="text-xs text-slate-500 font-medium mr-1 flex items-center gap-1">
                <Tag className="w-3 h-3" /> Filter:
              </span>
              {['All', 'Work', 'Personal', 'Dev'].map((cat) => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategoryFilter(cat)}
                  className={`text-xs px-3 py-1 rounded-full font-medium transition-all border whitespace-nowrap ${
                    selectedCategoryFilter === cat
                      ? 'bg-slate-800 border-indigo-500/50 text-indigo-300'
                      : 'bg-slate-950 border-slate-800/80 text-slate-400 hover:border-slate-700'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>

            {/* Todo List Items */}
            <div className="space-y-3">
              {filteredTodos.length === 0 ? (
                <div className="py-16 text-center bg-slate-950/40 rounded-xl border border-slate-800/60 flex flex-col items-center justify-center">
                  <div className="w-12 h-12 rounded-2xl bg-slate-900 border border-slate-800 flex items-center justify-center text-slate-500 mb-3">
                    <CheckSquare className="w-6 h-6" />
                  </div>
                  <h4 className="text-sm font-semibold text-slate-300 mb-1">No tasks found</h4>
                  <p className="text-xs text-slate-500 max-w-sm">
                    {searchQuery || selectedCategoryFilter !== 'All' 
                      ? 'Try adjusting your search query or category filters.'
                      : 'Get started by creating your first task above.'}
                  </p>
                </div>
              ) : (
                filteredTodos.map((todo) => (
                  <div
                    key={todo.id}
                    className={`group flex items-start justify-between gap-4 p-4 rounded-xl border transition-all duration-200 ${
                      todo.completed 
                        ? 'bg-slate-950/30 border-slate-900 opacity-75' 
                        : 'bg-slate-950/70 border-slate-800 hover:border-slate-700 shadow-sm hover:shadow-md'
                    }`}
                  >
                    <div className="flex items-start gap-3.5 min-w-0">
                      <button
                        onClick={() => toggleTodo(todo.id)}
                        className={`mt-0.5 w-5 h-5 rounded-lg flex items-center justify-center transition-all shrink-0 ${
                          todo.completed 
                            ? 'bg-emerald-500 text-slate-950 font-bold shadow-md shadow-emerald-500/20' 
                            : 'border border-slate-700 hover:border-indigo-500 bg-slate-900'
                        }`}
                      >
                        {todo.completed && <Check className="w-3.5 h-3.5 stroke-[3]" />}
                      </button>

                      <div className="min-w-0">
                        <p className={`text-sm font-medium leading-relaxed transition-all ${
                          todo.completed ? 'line-through text-slate-500' : 'text-slate-200'
                        }`}>
                          {todo.text}
                        </p>

                        <div className="flex flex-wrap items-center gap-2 mt-2">
                          {/* Category Badge */}
                          <span className="text-[10px] px-2 py-0.5 rounded bg-slate-900 border border-slate-800 text-slate-400 font-medium">
                            {todo.category}
                          </span>

                          {/* Priority Badge */}
                          <span className={`text-[10px] px-2 py-0.5 rounded font-medium capitalize border ${
                            todo.priority === 'high' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' :
                            todo.priority === 'medium' ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' :
                            'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                          }`}>
                            {todo.priority}
                          </span>

                          <span className="text-[10px] text-slate-500 flex items-center gap-1">
                            <Clock className="w-2.5 h-2.5" /> {todo.createdAt}
                          </span>
                        </div>
                      </div>
                    </div>

                    <button
                      onClick={() => deleteTodo(todo.id)}
                      className="opacity-0 group-hover:opacity-100 text-slate-500 hover:text-rose-400 p-2 rounded-lg hover:bg-rose-500/10 transition-all shrink-0"
                      title="Delete Task"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>

            {/* Footer Task Stats */}
            <div className="flex items-center justify-between text-xs text-slate-500 pt-2 border-t border-slate-800/60">
              <span>Showing {filteredTodos.length} of {todos.length} total tasks</span>
              <span className="font-medium text-slate-400">NovaForge Task Master v2.4</span>
            </div>

          </div>

        </div>

      </main>
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Sparkles, 
  Plus, 
  Check, 
  Trash2, 
  Search, 
  Calendar, 
  Flame, 
  CheckCircle2, 
  Circle, 
  Clock, 
  ArrowUpRight, 
  SlidersHorizontal, 
  Layers, 
  Zap,
  RefreshCw,
  Minus,
  Tag,
  CheckSquare
} from 'lucide-react';

interface Todo {
  id: string;
  text: string;
  completed: boolean;
  priority: 'low' | 'medium' | 'high';
  category: 'Work' | 'Personal' | 'Dev';
  createdAt: string;
}

export default function App() {
  // Counter state
  const [count, setCount] = useState<number>(12);
  const [step, setStep] = useState<number>(1);

  // Todo state
  const [todos, setTodos] = useState<Todo[]>([
    { id: '1', text: 'Deploy React 19 application to production cluster', completed: true, priority: 'high', category: 'Dev', createdAt: 'Today, 10:45 AM' },
    { id: '2', text: 'Refactor Tailwind CSS styling for high-contrast dark mode', completed: false, priority: 'medium', category: 'Work', createdAt: 'Today, 11:30 AM' },
    { id: '3', text: 'Review pull requests for authentication service update', completed: false, priority: 'high', category: 'Work', createdAt: 'Yesterday' },
    { id: '4', text: 'Prepare weekly sprint retro presentation and metrics', completed: false, priority: 'low', category: 'Personal', createdAt: '2 days ago' },
  ]);

  const [newText, setNewText] = useState('');
  const [newPriority, setNewPriority] = useState<'low' | 'medium' | 'high'>('medium');
  const [newCategory, setNewCategory] = useState<'Work' | 'Personal' | 'Dev'>('Work');

  const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState<string>('All');

  // Todo Actions
  const handleAddTodo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newText.trim()) return;

    const newTask: Todo = {
      id: Date.now().toString(),
      text: newText.trim(),
      completed: false,
      priority: newPriority,
      category: newCategory,
      createdAt: 'Just now',
    };

    setTodos([newTask, ...todos]);
    setNewText('');
  };

  const toggleTodo = (id: string) => {
    setTodos(todos.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const deleteTodo = (id: string) => {
    setTodos(todos.filter(t => t.id !== id));
  };

  // Filtered Todos
  const filteredTodos = todos.filter(todo => {
    const matchesSearch = todo.text.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesTab = 
      filter === 'all' ? true :
      filter === 'active' ? !todo.completed :
      todo.completed;
    const matchesCategory = selectedCategoryFilter === 'All' || todo.category === selectedCategoryFilter;

    return matchesSearch && matchesTab && matchesCategory;
  });

  const completedCount = todos.filter(t => t.completed).length;
  const completionPercentage = todos.length > 0 ? Math.round((completedCount / todos.length) * 100) : 0;

  return (
    <div className="min-h-screen bg-[#08090d] text-slate-100 flex flex-col font-sans selection:bg-indigo-500 selection:text-white">
      {/* Top Header */}
      <header className="border-b border-slate-800/80 bg-slate-950/60 backdrop-blur-xl sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 via-purple-600 to-pink-500 p-0.5 shadow-lg shadow-indigo-500/25 flex items-center justify-center">
              <div className="w-full h-full bg-slate-950 rounded-[10px] flex items-center justify-center">
                <Sparkles className="w-5 h-5 text-indigo-400 animate-pulse" />
              </div>
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl font-bold tracking-tight text-white">NovaForge</h1>
                <span className="text-xs px-2 py-0.5 rounded-full bg-indigo-500/10 border border-indigo-500/30 text-indigo-400 font-medium">Task Master</span>
              </div>
              <p className="text-xs text-slate-400">Next-gen productivity suite with interactive counter & task engine</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-lg bg-slate-900 border border-slate-800 text-xs text-slate-300">
              <Clock className="w-3.5 h-3.5 text-indigo-400" />
              <span>{new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</span>
            </div>
            <div className="flex items-center gap-2 px-3.5 py-1.5 rounded-xl bg-gradient-to-r from-indigo-600/20 to-purple-600/20 border border-indigo-500/30 text-indigo-300 text-xs font-medium">
              <Flame className="w-4 h-4 text-orange-400" />
              <span>{completionPercentage}% Completed</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 max-w-7xl w-full mx-auto p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

        {/* Left Column: Counter Widget & Quick Stats (4 Cols) */}
        <div className="lg:col-span-4 flex flex-col gap-6">

          {/* Interactive Counter Card */}
          <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-6 shadow-xl backdrop-blur-md relative overflow-hidden group">
            <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-indigo-600/10 rounded-full blur-3xl pointer-events-none group-hover:bg-indigo-600/20 transition-all duration-500"></div>

            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-lg bg-indigo-500/10 border border-indigo-500/30 flex items-center justify-center text-indigo-400">
                  <Zap className="w-4 h-4" />
                </div>
                <h2 className="text-sm font-semibold text-slate-200">Interactive Counter</h2>
              </div>
              <button 
                onClick={() => setCount(0)}
                className="text-slate-400 hover:text-white transition-colors p-1.5 rounded-lg hover:bg-slate-800"
                title="Reset Counter"
              >
                <RefreshCw className="w-3.5 h-3.5" />
              </button>
            </div>

            <div className="py-6 text-center bg-slate-950/50 rounded-xl border border-slate-800/60 mb-6 relative">
              <div className="text-xs uppercase tracking-wider text-slate-500 font-semibold mb-1">Current Value</div>
              <div className="text-5xl font-extrabold tracking-tight bg-gradient-to-r from-white via-slate-200 to-indigo-300 bg-clip-text text-transparent">
                {count}
              </div>
            </div>

            {/* Counter Controls */}
            <div className="grid grid-cols-2 gap-3 mb-4">
              <button
                onClick={() => setCount(c => c - step)}
                className="flex items-center justify-center gap-2 py-3 px-4 bg-slate-800 hover:bg-slate-700 active:scale-95 transition-all text-slate-200 rounded-xl font-medium text-sm border border-slate-700/60 shadow-md"
              >
                <Minus className="w-4 h-4" />
                <span>-{step}</span>
              </button>
              <button
                onClick={() => setCount(c => c + step)}
                className="flex items-center justify-center gap-2 py-3 px-4 bg-indigo-600 hover:bg-indigo-500 active:scale-95 transition-all text-white rounded-xl font-medium text-sm shadow-lg shadow-indigo-600/25"
              >
                <Plus className="w-4 h-4" />
                <span>+{step}</span>
              </button>
            </div>

            {/* Step Size Selector */}
            <div className="space-y-2">
              <div className="text-xs text-slate-400 font-medium flex items-center justify-between">
                <span>Increment Step Size</span>
                <span className="text-indigo-400 font-semibold">Step: {step}</span>
              </div>
              <div className="grid grid-cols-4 gap-2">
                {[1, 5, 10, 25].map((s) => (
                  <button
                    key={s}
                    onClick={() => setStep(s)}
                    className={`py-1.5 rounded-lg text-xs font-semibold transition-all border ${
                      step === s 
                        ? 'bg-indigo-500/20 border-indigo-500/50 text-indigo-300 shadow-sm shadow-indigo-500/20' 
                        : 'bg-slate-950/40 border-slate-800 text-slate-400 hover:bg-slate-800 hover:text-slate-200'
                    }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Quick Metrics Widget */}
          <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-6 shadow-xl backdrop-blur-md">
            <h3 className="text-sm font-semibold text-slate-200 mb-4 flex items-center gap-2">
              <Layers className="w-4 h-4 text-purple-400" />
              <span>System Productivity</span>
            </h3>

            <div className="space-y-3">
              <div className="flex items-center justify-between p-3 rounded-xl bg-slate-950/40 border border-slate-800/60">
                <span className="text-xs text-slate-400">Total Tasks Created</span>
                <span className="text-sm font-bold text-slate-200">{todos.length}</span>
              </div>
              <div className="flex items-center justify-between p-3 rounded-xl bg-slate-950/40 border border-slate-800/60">
                <span className="text-xs text-slate-400">Completed Items</span>
                <span className="text-sm font-bold text-emerald-400">{completedCount}</span>
              </div>
              <div className="flex items-center justify-between p-3 rounded-xl bg-slate-950/40 border border-slate-800/60">
                <span className="text-xs text-slate-400">Pending Actions</span>
                <span className="text-sm font-bold text-amber-400">{todos.length - completedCount}</span>
              </div>
            </div>
          </div>

        </div>

        {/* Right Column: Task Master Todo App (8 Cols) */}
        <div className="lg:col-span-8 flex flex-col gap-6">

          {/* Add Todo Form */}
          <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-6 shadow-xl backdrop-blur-md">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-base font-semibold text-slate-100 flex items-center gap-2">
                <CheckSquare className="w-5 h-5 text-indigo-400" />
                <span>Create New Task</span>
              </h2>
              <span className="text-xs text-slate-400">NovaForge Engine v2.4</span>
            </div>

            <form onSubmit={handleAddTodo} className="space-y-4">
              <div className="relative">
                <input
                  type="text"
                  value={newText}
                  onChange={(e) => setNewText(e.target.value)}
                  placeholder="What needs to be accomplished today?..."
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-slate-100 placeholder-slate-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all pr-12 shadow-inner"
                />
                <button
                  type="submit"
                  className="absolute right-2 top-2 bottom-2 px-3 bg-indigo-600 hover:bg-indigo-500 active:scale-95 transition-all text-white rounded-lg flex items-center justify-center shadow-md shadow-indigo-600/30"
                  title="Add Task"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>

              <div className="flex flex-wrap items-center justify-between gap-3 pt-1">
                <div className="flex flex-wrap items-center gap-3">
                  {/* Priority Selector */}
                  <div className="flex items-center gap-1.5 bg-slate-950/60 border border-slate-800 rounded-lg p-1">
                    <span className="text-[11px] text-slate-400 px-2 font-medium">Priority:</span>
                    {(['low', 'medium', 'high'] as const).map(p => (
                      <button
                        key={p}
                        type="button"
                        onClick={() => setNewPriority(p)}
                        className={`text-xs px-2.5 py-1 rounded-md capitalize font-medium transition-all ${
                          newPriority === p
                            ? p === 'high' ? 'bg-rose-500/20 text-rose-300 border border-rose-500/30'
                              : p === 'medium' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30'
                              : 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30'
                            : 'text-slate-400 hover:text-slate-200'
                        }`}
                      >
                        {p}
                      </button>
                    ))}
                  </div>

                  {/* Category Selector */}
                  <div className="flex items-center gap-1.5 bg-slate-950/60 border border-slate-800 rounded-lg p-1">
                    <span className="text-[11px] text-slate-400 px-2 font-medium">Category:</span>
                    {(['Work', 'Personal', 'Dev'] as const).map(c => (
                      <button
                        key={c}
                        type="button"
                        onClick={() => setNewCategory(c)}
                        className={`text-xs px-2.5 py-1 rounded-md font-medium transition-all ${
                          newCategory === c
                            ? 'bg-indigo-500/20 text-indigo-300 border border-indigo-500/30'
                            : 'text-slate-400 hover:text-slate-200'
                        }`}
                      >
                        {c}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </form>
          </div>

          {/* Task Management & Filters */}
          <div className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-6 shadow-xl backdrop-blur-md flex flex-col gap-5">

            {/* Search & Tabs Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              {/* Filter Tabs */}
              <div className="flex items-center gap-1 bg-slate-950 p-1 rounded-xl border border-slate-800">
                {(['all', 'active', 'completed'] as const).map((tab) => (
                  <button
                    key={tab}
                    onClick={() => setFilter(tab)}
                    className={`px-4 py-1.5 rounded-lg text-xs font-semibold capitalize transition-all ${
                      filter === tab
                        ? 'bg-indigo-600 text-white shadow-md shadow-indigo-600/30'
                        : 'text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    {tab}
                  </button>
                ))}
              </div>

              {/* Search input */}
              <div className="relative min-w-[220px]">
                <Search className="w-4 h-4 text-slate-500 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search tasks..."
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl pl-9 pr-3 py-1.5 text-xs text-slate-100 placeholder-slate-500 focus:outline-none focus:border-indigo-500 transition-all"
                />
              </div>
            </div>

            {/* Category Sub-filter pills */}
            <div className="flex items-center gap-2 overflow-x-auto pb-1">
              <span className="text-xs text-slate-500 font-medium mr-1 flex items-center gap-1">
                <Tag className="w-3 h-3" /> Filter:
              </span>
              {['All', 'Work', 'Personal', 'Dev'].map((cat) => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategoryFilter(cat)}
                  className={`text-xs px-3 py-1 rounded-full font-medium transition-all border whitespace-nowrap ${
                    selectedCategoryFilter === cat
                      ? 'bg-slate-800 border-indigo-500/50 text-indigo-300'
                      : 'bg-slate-950 border-slate-800/80 text-slate-400 hover:border-slate-700'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>

            {/* Todo List Items */}
            <div className="space-y-3">
              {filteredTodos.length === 0 ? (
                <div className="py-16 text-center bg-slate-950/40 rounded-xl border border-slate-800/60 flex flex-col items-center justify-center">
                  <div className="w-12 h-12 rounded-2xl bg-slate-900 border border-slate-800 flex items-center justify-center text-slate-500 mb-3">
                    <CheckSquare className="w-6 h-6" />
                  </div>
                  <h4 className="text-sm font-semibold text-slate-300 mb-1">No tasks found</h4>
                  <p className="text-xs text-slate-500 max-w-sm">
                    {searchQuery || selectedCategoryFilter !== 'All' 
                      ? 'Try adjusting your search query or category filters.'
                      : 'Get started by creating your first task above.'}
                  </p>
                </div>
              ) : (
                filteredTodos.map((todo) => (
                  <div
                    key={todo.id}
                    className={`group flex items-start justify-between gap-4 p-4 rounded-xl border transition-all duration-200 ${
                      todo.completed 
                        ? 'bg-slate-950/30 border-slate-900 opacity-75' 
                        : 'bg-slate-950/70 border-slate-800 hover:border-slate-700 shadow-sm hover:shadow-md'
                    }`}
                  >
                    <div className="flex items-start gap-3.5 min-w-0">
                      <button
                        onClick={() => toggleTodo(todo.id)}
                        className={`mt-0.5 w-5 h-5 rounded-lg flex items-center justify-center transition-all shrink-0 ${
                          todo.completed 
                            ? 'bg-emerald-500 text-slate-950 font-bold shadow-md shadow-emerald-500/20' 
                            : 'border border-slate-700 hover:border-indigo-500 bg-slate-900'
                        }`}
                      >
                        {todo.completed && <Check className="w-3.5 h-3.5 stroke-[3]" />}
                      </button>

                      <div className="min-w-0">
                        <p className={`text-sm font-medium leading-relaxed transition-all ${
                          todo.completed ? 'line-through text-slate-500' : 'text-slate-200'
                        }`}>
                          {todo.text}
                        </p>

                        <div className="flex flex-wrap items-center gap-2 mt-2">
                          {/* Category Badge */}
                          <span className="text-[10px] px-2 py-0.5 rounded bg-slate-900 border border-slate-800 text-slate-400 font-medium">
                            {todo.category}
                          </span>

                          {/* Priority Badge */}
                          <span className={`text-[10px] px-2 py-0.5 rounded font-medium capitalize border ${
                            todo.priority === 'high' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' :
                            todo.priority === 'medium' ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' :
                            'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                          }`}>
                            {todo.priority}
                          </span>

                          <span className="text-[10px] text-slate-500 flex items-center gap-1">
                            <Clock className="w-2.5 h-2.5" /> {todo.createdAt}
                          </span>
                        </div>
                      </div>
                    </div>

                    <button
                      onClick={() => deleteTodo(todo.id)}
                      className="opacity-0 group-hover:opacity-100 text-slate-500 hover:text-rose-400 p-2 rounded-lg hover:bg-rose-500/10 transition-all shrink-0"
                      title="Delete Task"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>

            {/* Footer Task Stats */}
            <div className="flex items-center justify-between text-xs text-slate-500 pt-2 border-t border-slate-800/60">
              <span>Showing {filteredTodos.length} of {todos.length} total tasks</span>
              <span className="font-medium text-slate-400">NovaForge Task Master v2.4</span>
            </div>

          </div>

        </div>

      </main>
    </div>
  );
}

