import React, { useState } from 'react';
import { 
  Sparkles, 
  Plus, 
  Trash2, 
  CheckCircle2, 
  Circle, 
  ListTodo, 
  Tag, 
  Flame, 
  RotateCcw, 
  Search, 
  Check, 
  Clock, 
  TrendingUp, 
  ShieldCheck,
  AlertCircle
} from 'lucide-react';

interface Todo {
  id: string;
  text: string;
  completed: boolean;
  priority: 'High' | 'Medium' | 'Low';
  category: string;
  createdAt: string;
}

export default function App() {
  // Counter State
  const [sessionCount, setSessionCount] = useState(12);

  // Todo State
  const [todos, setTodos] = useState<Todo[]>([
    { id: '1', text: 'Architect NovaForge v2.4 Microfrontend Pipeline', completed: true, priority: 'High', category: 'Architecture', createdAt: 'Today, 09:30 AM' },
    { id: '2', text: 'Optimize React 19 Concurrent rendering hooks', completed: false, priority: 'High', category: 'Engineering', createdAt: 'Today, 10:15 AM' },
    { id: '3', text: 'Review Tailwind CSS v4 token configuration & themes', completed: false, priority: 'Medium', category: 'Design', createdAt: 'Today, 11:00 AM' },
    { id: '4', text: 'Deploy staging environment to Vercel edge network', completed: false, priority: 'Low', category: 'DevOps', createdAt: 'Yesterday, 04:45 PM' }
  ]);

  const [inputVal, setInputVal] = useState('');
  const [priority, setPriority] = useState<'High' | 'Medium' | 'Low'>('Medium');
  const [category, setCategory] = useState('Engineering');
  const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');

  // Add todo handler
  const handleAddTodo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputVal.trim()) return;

    const newTodo: Todo = {
      id: Date.now().toString(),
      text: inputVal.trim(),
      completed: false,
      priority,
      category,
      createdAt: 'Just now'
    };

    setTodos([newTodo, ...todos]);
    setInputVal('');
    setSessionCount(prev => prev + 1);
  };

  const toggleTodo = (id: string) => {
    setTodos(todos.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const deleteTodo = (id: string) => {
    setTodos(todos.filter(t => t.id !== id));
  };

  // Filtered todos
  const categories = ['All', 'Engineering', 'Architecture', 'Design', 'DevOps'];

  const filteredTodos = todos.filter(t => {
    const matchesSearch = t.text.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesTab = filter === 'all' ? true : filter === 'active' ? !t.completed : t.completed;
    const matchesCategory = selectedCategory === 'All' || t.category === selectedCategory;
    return matchesSearch && matchesTab && matchesCategory;
  });

  const completedCount = todos.filter(t => t.completed).length;
  const progressPercentage = todos.length > 0 ? Math.round((completedCount / todos.length) * 100) : 0;

  return (
    <div className="min-h-screen bg-[#08090d] text-slate-100 flex flex-col font-sans selection:bg-indigo-500 selection:text-white">
      {/* Background ambient glow */}
      <div className="absolute top-0 left-1/4 w-96 h-96 bg-indigo-600/10 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute top-1/3 right-1/4 w-96 h-96 bg-violet-600/10 rounded-full blur-3xl pointer-events-none" />

      {/* Header */}
      <header className="border-b border-white/10 bg-slate-900/60 backdrop-blur-md sticky top-0 z-30">
        <div className="max-w-6xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-500 flex items-center justify-center shadow-lg shadow-indigo-500/30">
              <ListTodo className="w-5 h-5 text-white" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl font-bold tracking-tight bg-gradient-to-r from-white via-slate-200 to-indigo-200 bg-clip-text text-transparent">
                  ACCEPTANCE TEST HEADING V2
                </h1>
                <span className="px-2 py-0.5 text-[10px] font-semibold bg-indigo-500/20 border border-indigo-500/30 text-indigo-300 rounded-full">
                  v2.4 Pro
                </span>
              </div>
              <p className="text-xs text-slate-400">Next-gen React 19 task orchestration & velocity suite</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            {/* Counter Widget in Header */}
            <div className="hidden sm:flex items-center gap-3 bg-slate-950/80 border border-white/10 px-4 py-2 rounded-xl">
              <div className="flex items-center gap-2">
                <Flame className="w-4 h-4 text-amber-400 animate-pulse" />
                <span className="text-xs text-slate-400">Action Index:</span>
                <span className="text-sm font-bold text-indigo-400">{sessionCount}</span>
              </div>
              <div className="h-4 w-px bg-white/10" />
              <div className="flex items-center gap-1">
                <button 
                  onClick={() => setSessionCount(c => Math.max(0, c - 1))}
                  className="w-6 h-6 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 flex items-center justify-center text-xs transition-colors"
                  title="Decrement counter"
                >
                  -
                </button>
                <button 
                  onClick={() => setSessionCount(c => c + 1)}
                  className="w-6 h-6 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white flex items-center justify-center text-xs transition-colors shadow-sm shadow-indigo-500/30"
                  title="Increment counter"
                >
                  +
                </button>
                <button 
                  onClick={() => setSessionCount(0)}
                  className="w-6 h-6 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white flex items-center justify-center text-xs transition-colors"
                  title="Reset counter"
                >
                  <RotateCcw className="w-3 h-3" />
                </button>
              </div>
            </div>

            <div className="flex items-center gap-2 pl-2 border-l border-white/10">
              <div className="w-9 h-9 rounded-full bg-gradient-to-r from-indigo-500 to-purple-500 p-0.5 shadow-md">
                <div className="w-full h-full bg-slate-900 rounded-full flex items-center justify-center font-bold text-xs text-indigo-300">
                  NF
                </div>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Container */}
      <main className="max-w-6xl mx-auto px-6 py-8 flex-1 w-full grid grid-cols-1 lg:grid-cols-4 gap-8">

        {/* Left Sidebar: Quick Stats & Filters */}
        <aside className="lg:col-span-1 space-y-6">
          {/* Progress Card */}
          <div className="bg-slate-900/80 border border-white/10 rounded-2xl p-5 shadow-xl backdrop-blur-md relative overflow-hidden">
            <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-500/10 rounded-full blur-xl pointer-events-none" />
            <h3 className="text-sm font-semibold text-slate-300 mb-3 flex items-center justify-between">
              <span>Velocity Overview</span>
              <TrendingUp className="w-4 h-4 text-indigo-400" />
            </h3>

            <div className="flex items-end justify-between mb-2">
              <span className="text-3xl font-extrabold text-white">{completedCount} <span className="text-sm font-normal text-slate-400">/ {todos.length} done</span></span>
              <span className="text-sm font-bold text-indigo-400">{progressPercentage}%</span>
            </div>

            {/* Progress Bar */}
            <div className="w-full h-2.5 bg-slate-800 rounded-full overflow-hidden mb-4">
              <div 
                className="h-full bg-gradient-to-r from-indigo-500 to-violet-500 transition-all duration-500 rounded-full"
                style={{ width: `${progressPercentage}%` }}
              />
            </div>

            <div className="grid grid-cols-2 gap-2 pt-2 border-t border-white/5 text-xs text-slate-400">
              <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 rounded-full bg-amber-400" />
                <span>{todos.filter(t => !t.completed).length} Pending</span>
              </div>
              <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 rounded-full bg-emerald-400" />
                <span>{completedCount} Completed</span>
              </div>
            </div>
          </div>

          {/* Interactive Counter Card (Mobile / Extra) */}
          <div className="bg-slate-900/80 border border-white/10 rounded-2xl p-5 shadow-xl backdrop-blur-md lg:hidden">
            <h3 className="text-sm font-semibold text-slate-300 mb-3 flex items-center justify-between">
              <span>Interactive Counter</span>
              <Sparkles className="w-4 h-4 text-amber-400" />
            </h3>
            <div className="flex items-center justify-between bg-slate-950 p-3 rounded-xl border border-white/5">
              <span className="text-xl font-bold text-indigo-400">{sessionCount}</span>
              <div className="flex gap-2">
                <button 
                  onClick={() => setSessionCount(c => Math.max(0, c - 1))}
                  className="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm"
                >
                  -
                </button>
                <button 
                  onClick={() => setSessionCount(c => c + 1)}
                  className="px-3 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-sm shadow-sm"
                >
                  +
                </button>
              </div>
            </div>
          </div>

          {/* Categories Filter */}
          <div className="bg-slate-900/80 border border-white/10 rounded-2xl p-5 shadow-xl backdrop-blur-md">
            <h3 className="text-sm font-semibold text-slate-300 mb-3 flex items-center gap-2">
              <Tag className="w-4 h-4 text-indigo-400" />
              <span>Categories</span>
            </h3>
            <div className="space-y-1">
              {categories.map(cat => {
                const count = cat === 'All' ? todos.length : todos.filter(t => t.category === cat).length;
                return (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-medium transition-all ${
                      selectedCategory === cat 
                        ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' 
                        : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'
                    }`}
                  >
                    <span>{cat}</span>
                    <span className="px-2 py-0.5 rounded-full bg-slate-800 text-[10px] text-slate-300">
                      {count}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        </aside>

        {/* Main Content Area: Todo Manager */}
        <section className="lg:col-span-3 space-y-6">

          {/* Add Todo Form */}
          <div className="bg-slate-900/80 border border-white/10 rounded-2xl p-6 shadow-xl backdrop-blur-md">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-indigo-400" />
              <span>Create New Task</span>
            </h2>

            <form onSubmit={handleAddTodo} className="space-y-4">
              <div className="relative">
                <input 
                  type="text"
                  value={inputVal}
                  onChange={(e) => setInputVal(e.target.value)}
                  placeholder="What needs to be accomplished in NovaForge today?..."
                  className="w-full bg-slate-950 border border-white/10 rounded-xl px-4 py-3.5 pl-4 pr-12 text-slate-100 placeholder-slate-500 text-sm focus:outline-none focus:border-indigo-500 transition-all shadow-inner"
                />
                <button
