              <button
                onClick={() => setCount(c => c + step)}
                className="flex items-center justify-center gap-1 bg-indigo-600 hover:bg-indigo-500 text-white py-2.5 px-3 rounded-xl shadow-lg shadow-indigo-600/20 active:scale-95 transition-all text-sm font-medium"
              >
                <PlusCircle className="w-4 h-4" />
                <span>Add</span>
              </button>
            </div>

            {/* Step Modifiers */}
            <div className="pt-3 border-t border-slate-800 flex items-center justify-between text-xs text-slate-400">
              <span>Step size:</span>
              <div className="flex gap-1.5">
                {[1, 5, 10].map((s) => (
                  <button
                    key={s}
                    onClick={() => setStep(s)}
                    className={`px-2.5 py-1 rounded-lg font-medium transition-all ${
                      step === s 
                        ? 'bg-indigo-500 text-white shadow-sm' 
                        : 'bg-slate-800/60 hover:bg-slate-800 text-slate-300'
                    }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Quick Metrics Widget */}
          <div className="bg-slate-900/90 border border-slate-800/80 rounded-2xl p-6 shadow-xl space-y-4">
            <h3 className="text-sm font-semibold uppercase tracking-wider text-slate-400">System Metrics</h3>
            <div className="space-y-3">
              <div>
                <div className="flex justify-between text-xs mb-1">
                  <span className="text-slate-300">Task Completion Rate</span>
                  <span className="text-indigo-400 font-medium">{progressPercentage}%</span>
                </div>
                <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-indigo-500 to-violet-500 transition-all duration-500 rounded-full" 
                    style={{ width: `${progressPercentage}%` }}
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3 pt-2">
                <div className="bg-slate-800/40 border border-slate-800 rounded-xl p-3 text-center">
                  <span className="block text-2xl font-bold text-white">{tasks.filter(t => !t.completed).length}</span>
                  <span className="text-xs text-slate-400">Active Tasks</span>
                </div>
                <div className="bg-slate-800/40 border border-slate-800 rounded-xl p-3 text-center">
                  <span className="block text-2xl font-bold text-emerald-400">{completedCount}</span>
                  <span className="text-xs text-slate-400">Completed</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Right Main Column: Task Master */}
        <div className="lg:col-span-2 space-y-6">

          {/* Add Task Form */}
          <div className="bg-slate-900/90 border border-slate-800/80 rounded-2xl p-6 shadow-xl">
            <h2 className="text-sm font-semibold uppercase tracking-wider text-slate-400 mb-4 flex items-center gap-2">
              <CheckSquare className="w-4 h-4 text-indigo-400" />
              Create New Task
            </h2>
            <form onSubmit={handleAddTask} className="space-y-4">
              <div>
                <input
                  type="text"
                  value={newTaskText}
                  onChange={(e) => setNewTaskText(e.target.value)}
                  placeholder="What needs to be accomplished in NovaForge?"
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none focus:border-indigo-500 transition-all shadow-inner"
                />
              </div>

              <div className="flex flex-wrap items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  {/* Priority selector */}
                  <div className="flex items-center gap-1.5 bg-slate-950 border border-slate-800 rounded-xl p-1">
                    {(['low', 'medium', 'high'] as const).map((p) => (
                      <button
                        key={p}
                        type="button"
                        onClick={() => setNewTaskPriority(p)}
                        className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-all ${
                          newTaskPriority === p
                            ? p === 'high' ? 'bg-rose-500/20 text-rose-300 border border-rose-500/40' :
                              p === 'medium' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/40' :
                              'bg-indigo-500/20 text-indigo-300 border border-indigo-500/40'
                            : 'text-slate-400 hover:text-white'
                        }`}
                      >
                        {p}
                      </button>
                    ))}
                  </div>

                  {/* Category select */}
                  <select
                    value={newTaskCategory}
                    onChange={(e) => setNewTaskCategory(e.target.value)}
                    className="bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-slate-300 focus:outline-none focus:border-indigo-500"
                  >
                    <option value="Frontend">Frontend</option>
                    <option value="DevOps">DevOps</option>
                    <option value="Design">Design</option>
                    <option value="QA">QA</option>
                    <option value="Backend">Backend</option>
                  </select>
                </div>

                <button
                  type="submit"
                  className="inline-flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-500 active:scale-95 transition-all text-white font-medium text-xs rounded-xl shadow-lg shadow-indigo-600/20"
                >
                  <Plus className="w-4 h-4" />
                  <span>Add Task</span>
                </button>
              </div>
            </form>
          </div>

          {/* Task Filtering & Search Bar */}
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-slate-900/50 p-3 rounded-2xl border border-slate-800/60">
            <div className="flex items-center gap-1 w-full sm:w-auto bg-slate-950 p-1 rounded-xl border border-slate-800">
              {(['all', 'active', 'completed'] as const).map((tab) => (
                <button
                  key={tab}
                  onClick={() => setFilter(tab)}
                  className={`flex-1 sm:flex-none px-4 py-1.5 rounded-lg text-xs font-medium capitalize transition-all ${
                    filter === tab
                      ? 'bg-indigo-600 text-white shadow-sm'
                      : 'text-slate-400 hover:text-slate-200'
                  }`}
                >
                  {tab}
                </button>
              ))}
            </div>

            <div className="relative w-full sm:w-64">
              <Search className="w-4 h-4 text-slate-500 absolute left-3 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Search tasks..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl pl-9 pr-4 py-2 text-xs text-slate-200 placeholder:text-slate-500 focus:outline-none focus:border-indigo-500 transition-all"
              />
            </div>
          </div>

          {/* Task List */}
          <div className="space-y-3">
            {filteredTasks.length === 0 ? (
              <div className="text-center py-12 bg-slate-900/40 border border-slate-800/80 rounded-2xl p-8">
                <div className="w-12 h-12 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-3 text-slate-500">
                  <CheckSquare className="w-6 h-6" />
                </div>
                <h3 className="text-sm font-semibold text-slate-300">No tasks found</h3>
                <p className="text-xs text-slate-500 mt-1">Try creating a new task or clearing your search filters.</p>
              </div>
            ) : (
              filteredTasks.map((task) => (
                <div
                  key={task.id}
                  className={`group flex items-center justify-between p-4 rounded-2xl border transition-all ${
                    task.completed
                      ? 'bg-slate-950/40 border-slate-900 text-slate-500'
                      : 'bg-slate-900/90 border-slate-800/80 text-slate-100 hover:border-indigo-500/30 shadow-lg'
                  }`}
                >
                  <div className="flex items-center gap-3.5 min-w-0 flex-1">
                    <button
                      onClick={() => toggleTask(task.id)}
                      className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${
                        task.completed 
                          ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/40' 
                          : 'bg-slate-950 border border-slate-700 hover:border-indigo-500 text-transparent'
                      }`}
                    >
                      <Check className={`w-3.5 h-3.5 ${task.completed ? 'opacity-100' : 'opacity-0'}`} />
                    </button>
                    <div className="min-w-0 flex-1">
                      <p className={`text-sm font-medium truncate ${task.completed ? 'line-through text-slate-500' : 'text-slate-200'}`}>
                        {task.text}
                      </p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className={`text-[10px] px-2 py-0.5 rounded font-medium uppercase tracking-wide ${
                          task.priority === 'high' ? 'bg-rose-500/10 text-rose-400 border border-rose-500/20' :
                          task.priority === 'medium' ? 'bg-amber-500/10 text-amber-400 border border-amber-500/20' :
                          'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20'
                        }`}>
                          {task.priority}
                        </span>
                        <span className="text-[10px] bg-slate-800/80 text-slate-400 px-2 py-0.5 rounded flex items-center gap-1">
                          <Tag className="w-2.5 h-2.5" />
                          {task.category}
                        </span>
                        <span className="text-[10px] text-slate-500 flex items-center gap-1">
                          <Calendar className="w-2.5 h-2.5" />
                          {task.dueDate}
                        </span>
                      </div>
                    </div>
                  </div>

                  <button
                    onClick={() => deleteTask(task.id)}
                    className="opacity-0 group-hover:opacity-100 p-2 text-slate-500 hover:text-rose-400 transition-all rounded-lg hover:bg-rose-500/10 ml-2"
                    title="Delete task"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))
            )}
          </div>
        </div>

      </main>

      {/* Footer */}
      <footer className="border-t border-white/5 py-6 text-center text-xs text-slate-500 mt-12">
        <p>NovaForge Task Master &copy; {new Date().getFullYear()} — Built with React 19, TypeScript & Tailwind CSS.</p>
      </footer>
    </div>
  );
}

import React, { useState } from 'react';
import { Sparkles, ArrowRight, Code2 } from 'lucide-react';

export default function App() {
  const [count, setCount] = useState(0);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col items-center justify-center p-6">
      <div className="max-w-md w-full bg-slate-900 border border-slate-800 rounded-2xl p-8 shadow-2xl text-center">
        <div className="w-12 h-12 bg-indigo-500/10 border border-indigo-500/30 rounded-xl flex items-center justify-center mx-auto mb-4 text-indigo-400">
          <Sparkles className="w-6 h-6 animate-pulse" />
        </div>
        <h1 className="text-2xl font-bold tracking-tight mb-2">Welcome to Acceptance Test App</h1>
        <p className="text-slate-400 text-sm mb-6">
          Automated Acceptance Verification Project for Lovable/Bolt AI Builder
        </p>
        <button
          onClick={() => setCount((c) => c + 1)}
          className="inline-flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-500 active:scale-95 transition-all text-white font-medium text-sm rounded-lg shadow-lg shadow-indigo-500/20"
        >
          <span>Interactions: {count}</span>
          <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}
